import sqlite3
import json
import ast

# 数据库路径配置
SQLITE_PATHS = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db"
}

def parse_json_string(s):
    """安全地解析可能为JSON或Python字典格式的字符串"""
    if not s:
        return {}
    try:
        return json.loads(s)
    except json.JSONDecodeError:
        try:
            return ast.literal_eval(s)
        except (ValueError, SyntaxError):
            return {}

def is_open_between_9_and_11(hours_dict):
    """检查营业时间是否覆盖 21:00 到 23:00"""
    if not hours_dict:
        return False

    for day, time_range in hours_dict.items():
        if time_range == '0:0-0:0':  # 24小时营业
            return True

        try:
            start_str, end_str = time_range.split('-')

            def to_float_hours(t_str):
                h, m = map(int, t_str.split(':'))
                return h + m / 60.0

            start_h = to_float_hours(start_str)
            end_h = to_float_hours(end_str)

            # 处理跨夜营业的情况 (例如 17:00-02:00)
            if end_h <= start_h:
                end_h += 24.0

            # 目标时间段：21:00 (21.0) 到 23:00 (23.0)
            # 必须在21:00或之前开门，且在23:00或之后关门
            if start_h <= 21.0 and end_h >= 23.0:
                return True
        except Exception:
            continue

    return False

def is_good_for_dinner(attributes_dict):
    """检查属性中是否明确标明适合晚餐"""
    if not attributes_dict:
        return False

    good_for_meal = attributes_dict.get('GoodForMeal', '{}')
    if isinstance(good_for_meal, str):
        meal_dict = parse_json_string(good_for_meal)
    else:
        meal_dict = good_for_meal

    return meal_dict.get('dinner') is True

def find_dinner_restaurants():
    # 连接到business数据库
    conn = sqlite3.connect(SQLITE_PATHS['business'])
    cursor = conn.cursor()

    # Step 1: SQL初步过滤
    # 筛选类别包含Restaurants，属性包含dinner，且有营业时间数据的商家
    query = """
        SELECT name, hours, attributes, stars, review_count
        FROM business 
        WHERE categories LIKE '%Restaurants%' 
          AND attributes LIKE '%dinner%'
          AND hours IS NOT NULL
    """

    try:
        cursor.execute(query)
        rows = cursor.fetchall()

        final_restaurants = []

        # Step 2: Python精确过滤
        for row in rows:
            name, hours_str, attributes_str, stars, review_count = row

            attributes_dict = parse_json_string(attributes_str)
            hours_dict = parse_json_string(hours_str)

            # 验证适合晚餐且在9-11pm营业
            if is_good_for_dinner(attributes_dict) and is_open_between_9_and_11(hours_dict):
                final_restaurants.append({
                    'name': name,
                    'stars': stars,
                    'review_count': review_count,
                    'hours': hours_dict
                })

        # 按评分和评论数排序，推荐最好的餐厅
        final_restaurants.sort(key=lambda x: (x['stars'], x['review_count']), reverse=True)

        # 输出结果
        print(f"Found {len(final_restaurants)} restaurants good for dinner between 9-11 PM.")
        print("\nTop 10 Recommendations:")
        for i, r in enumerate(final_restaurants[:10], 1):
            print(f"{i}. {r['name']} (Stars: {r['stars']}, Reviews: {r['review_count']})")

        return final_restaurants

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        conn.close()

if __name__ == '__main__':
    find_dinner_restaurants()
